// Explicit operator experiment: actual retained equal operands, no serving selection.
use cudarc::{driver::{CudaDevice,CudaFunction,DevicePtr,sys},cublas::{result as br,sys as bs}};
use serde::{Deserialize};use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::PathBuf};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Identity{path:PathBuf,bytes:usize,sha256:String}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
impl Identity{fn read(&self)->Result<Vec<u8>,String>{let b=fs::read(&self.path).map_err(|e|e.to_string())?;if b.len()!=self.bytes||hash(&b)!=self.sha256{return Err(format!("identity {}",self.path.display()))}Ok(b)}}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Plan{controls:bool,profile:bool,mode:String,reference_weights:Identity,gpu_uuid:String,provenance:Identity,prefill_ptx:Identity,query:Identity,cache:Identity,selected:Identity,expected_prefill:Identity,expected_decode:Identity,heads:usize,ccd:usize,nope:usize,rope:usize,prefix:usize,scale:f32,batches:Vec<usize>}
fn floats(b:&[u8])->Result<Vec<f32>,String>{if b.len()%4!=0{return Err("F32 extent".into())}let v:Vec<_>=b.chunks_exact(4).map(|x|f32::from_le_bytes(x.try_into().unwrap())).collect();if v.iter().any(|x|!x.is_finite()){return Err("nonfinite F32".into())}Ok(v)}
fn serial(v:&[f32])->Vec<u8>{v.iter().flat_map(|x|x.to_le_bytes()).collect()}
struct Blas(bs::cublasHandle_t);impl Drop for Blas{fn drop(&mut self){unsafe{let _=br::destroy_handle(self.0);}}}
unsafe fn launch(f:&CudaFunction,grid:u32,stream:sys::CUstream,args:&mut[*mut std::ffi::c_void])->Result<(),String>{sys::lib().cuLaunchKernel(f.cu_function(),grid,1,1,256,1,1,0,stream,args.as_mut_ptr(),std::ptr::null_mut()).result().map_err(|e|format!("launch {e:?}"))}
macro_rules! args {($($x:ident),*)=>{&mut[$(&mut $x as *mut _ as *mut std::ffi::c_void),*]};}
fn compare(x:&[f32],y:&[f32])->Result<serde_json::Value,String>{if x.len()!=y.len(){return Err("comparison extent".into())}let(mut n,mut first,mut abs,mut se,mut sy)=(0,None,0f64,0f64,0f64);for(i,(&a,&b))in x.iter().zip(y).enumerate(){if !a.is_finite()||!b.is_finite(){return Err("nonfinite output".into())}if a.to_bits()!=b.to_bits(){n+=1;if first.is_none(){first=Some(i)}}let d=(a as f64-b as f64).abs();abs=abs.max(d);se+=d*d;sy+=(b as f64)*(b as f64);}Ok(json!({"elements":x.len(),"different":n,"first":first,"max_abs":abs,"relative_l2":(se/sy).sqrt()}))}
fn run(plan:&str,out:&str)->Result<(),String>{
 let p:Plan=serde_json::from_slice(&fs::read(plan).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let proof:serde_json::Value=serde_json::from_slice(&p.provenance.read()?).map_err(|e|e.to_string())?;if proof["collectionPassed"]!=true{return Err("unqualified provenance".into())}
 if p.rope!=0||p.ccd==0||p.ccd%16!=0||p.heads==0||p.nope==0||p.prefix==0||!p.scale.is_finite()||p.scale<=0.0||p.batches.is_empty()||p.batches[0]!=1{return Err("experiment requires admitted zero-RoPE geometry and singleton-first controls".into())}
 let q=floats(&p.query.read()?)?;let cache=p.cache.read()?;let ids=p.selected.read()?;if ids.len()%4!=0{return Err("selected extent".into())}let selected:Vec<i32>=ids.chunks_exact(4).map(|x|i32::from_le_bytes(x.try_into().unwrap())).collect();let count=selected.len();let expected=floats(&p.expected_prefill.read()?)?;let old=floats(&p.expected_decode.read()?)?;
 if q.len()!=p.heads*p.ccd||cache.len()!=p.prefix*(p.ccd/16)*14||expected.len()!=q.len()||old.len()!=q.len()||count==0||selected.iter().any(|&i|i>=p.prefix as i32){return Err("actual operands geometry/causality".into())}
 let dev=CudaDevice::new_with_stream(0).map_err(|e|e.to_string())?;let mut uuid=unsafe{std::mem::zeroed::<sys::CUuuid>()};unsafe{sys::lib().cuDeviceGetUuid_v2(&mut uuid,*dev.cu_device())}.result().map_err(|e|e.to_string())?;let h=uuid.bytes.iter().map(|b|format!("{:02x}",*b as u8)).collect::<String>();let actual=format!("GPU-{}-{}-{}-{}-{}",&h[..8],&h[8..12],&h[12..16],&h[16..20],&h[20..]);if actual!=p.gpu_uuid{return Err("physical device mismatch".into())}
 let ptx=String::from_utf8(p.prefill_ptx.read()?).map_err(|e|e.to_string())?;dev.load_ptx(ptx.into(),"retained65",&["mla_prefill_gather_query_k6_f32_structured_kernel","mla_prefill_softmax_weights_warp_f32_kernel"]).map_err(|e|e.to_string())?;let gather=dev.get_func("retained65","mla_prefill_gather_query_k6_f32_structured_kernel").ok_or("gather absent")?;let softmax=dev.get_func("retained65","mla_prefill_softmax_weights_warp_f32_kernel").ok_or("softmax absent")?;
 let dcache=dev.htod_sync_copy(&cache).map_err(|e|e.to_string())?;let stream=*dev.cu_stream();let blas=Blas(br::create_handle().map_err(|e|e.to_string())?);unsafe{br::set_stream(blas.0,stream as bs::cudaStream_t)}.map_err(|e|e.to_string())?;
 if p.mode!="lt"{return Err("explicit lt mode required".into())}let fixed_weights=floats(&p.reference_weights.read()?)?;if fixed_weights.len()!=p.heads*count{return Err("fixed actual weight row extent".into())}
 let lt_score=lt::Probe::new(dev.clone(),p.ccd,p.heads,count,p.scale,true)?;let lt_output=lt::Probe::new(dev.clone(),p.ccd,p.heads,count,p.scale,false)?;let mut lt_controls=Vec::new();
 let root=PathBuf::from(out);fs::create_dir(&root).map_err(|e|e.to_string())?;let mut controls=Vec::new();let mut singleton=None;
 for &batch in &p.batches{
  if batch==0||batch>i32::MAX as usize{return Err("batch extent".into())}let copies=|v:&[f32]|v.repeat(batch);let dq=dev.htod_sync_copy(&copies(&q)).map_err(|e|e.to_string())?;let dids=dev.htod_sync_copy(&selected.repeat(batch)).map_err(|e|e.to_string())?;let positions=dev.htod_sync_copy(&vec![(p.prefix-1)as i32;batch]).map_err(|e|e.to_string())?;
  let dg=dev.alloc_zeros::<f32>(batch*count*p.ccd).map_err(|e|e.to_string())?;let dquery=dev.alloc_zeros::<f32>(batch*p.heads*p.ccd).map_err(|e|e.to_string())?;let ds=dev.alloc_zeros::<f32>(batch*p.heads*count).map_err(|e|e.to_string())?;let dw=dev.alloc_zeros::<f32>(batch*p.heads*count).map_err(|e|e.to_string())?;let dout=dev.alloc_zeros::<f32>(batch*p.heads*p.ccd).map_err(|e|e.to_string())?;
  let(mut g0,mut g1,mut g2,mut g3,mut g4,mut g5,mut g6,mut g7,mut g8)=(*dg.device_ptr(),*dquery.device_ptr(),*ds.device_ptr(),*dq.device_ptr(),*dq.device_ptr(),*dcache.device_ptr(),0u64,*dids.device_ptr(),*positions.device_ptr());
  let(mut g9,mut g10,mut g11,mut g12,mut g13,mut g14,mut g15,mut g16,mut g17)=(0i32,batch as i32,p.heads as i32,p.nope as i32,p.nope as i32,0i32,p.ccd as i32,count as i32,p.prefix as i32);
  let grid=batch*(count.div_ceil(8)+p.heads.div_ceil(8)+1);unsafe{launch(&gather,u32::try_from(grid).map_err(|_|"grid overflow")?,stream,args!(g0,g1,g2,g3,g4,g5,g6,g7,g8,g9,g10,g11,g12,g13,g14,g15,g16,g17))?;}
  let mask:Vec<f32>=(0..batch*p.heads).flat_map(|_|selected.iter().map(|&i|if i>=0&&i<p.prefix as i32{0.0}else{f32::NEG_INFINITY})).collect();
 lt_controls.push(lt_score.run(&dg,&dquery,&mask,batch,&root,"lt-score",false,p.profile,p.controls)?);let fixed=dev.htod_sync_copy(&fixed_weights.repeat(batch)).map_err(|e|e.to_string())?;lt_controls.push(lt_output.run(&dg,&fixed,&vec![0.0;batch*p.heads*p.ccd],batch,&root,"lt-output",false,p.profile,p.controls)?);
 let(zero,one)=(0f32,1f32);unsafe{br::gemm_strided_batched_ex(blas.0,bs::cublasOperation_t::CUBLAS_OP_T,bs::cublasOperation_t::CUBLAS_OP_N,count as i32,p.heads as i32,p.ccd as i32,&p.scale as *const _ as _,*dg.device_ptr() as _,bs::cudaDataType::CUDA_R_32F,p.ccd as i32,(count*p.ccd)as i64,*dquery.device_ptr() as _,bs::cudaDataType::CUDA_R_32F,p.ccd as i32,(p.heads*p.ccd)as i64,&one as *const _ as _,*ds.device_ptr()as _,bs::cudaDataType::CUDA_R_32F,count as i32,(p.heads*count)as i64,batch as i32,bs::cublasComputeType_t::CUBLAS_COMPUTE_32F_PEDANTIC,bs::cublasGemmAlgo_t::CUBLAS_GEMM_DEFAULT)}.map_err(|e|e.to_string())?;
  let(mut s0,mut s1,mut s2,mut s3,mut s4)=(*dw.device_ptr(),*ds.device_ptr(),batch as i32,p.heads as i32,count as i32);unsafe{launch(&softmax,(batch*p.heads).div_ceil(8)as u32,stream,args!(s0,s1,s2,s3,s4))?;br::gemm_strided_batched_ex(blas.0,bs::cublasOperation_t::CUBLAS_OP_N,bs::cublasOperation_t::CUBLAS_OP_N,p.ccd as i32,p.heads as i32,count as i32,&one as *const _ as _,*dg.device_ptr()as _,bs::cudaDataType::CUDA_R_32F,p.ccd as i32,(count*p.ccd)as i64,*dw.device_ptr()as _,bs::cudaDataType::CUDA_R_32F,count as i32,(p.heads*count)as i64,&zero as *const _ as _,*dout.device_ptr()as _,bs::cudaDataType::CUDA_R_32F,p.ccd as i32,(p.heads*p.ccd)as i64,batch as i32,bs::cublasComputeType_t::CUBLAS_COMPUTE_32F_PEDANTIC,bs::cublasGemmAlgo_t::CUBLAS_GEMM_DEFAULT).map_err(|e|e.to_string())?;}
  dev.synchronize().map_err(|e|e.to_string())?;let output=dev.dtoh_sync_copy(&dout).map_err(|e|e.to_string())?;let unit=output[..q.len()].to_vec();if batch==1{singleton=Some(unit.clone())}let reference=singleton.as_ref().ok_or("singleton absent")?;let mut all_equal=true;for row in output.chunks_exact(q.len()){if row.iter().zip(reference).any(|(a,b)|a.to_bits()!=b.to_bits()){all_equal=false;}}
  fs::write(root.join(format!("batch{batch}-output.f32")),serial(&output)).map_err(|e|e.to_string())?;let scores=dev.dtoh_sync_copy(&ds).map_err(|e|e.to_string())?;let weights=dev.dtoh_sync_copy(&dw).map_err(|e|e.to_string())?;fs::write(root.join(format!("batch{batch}-scores.f32")),serial(&scores)).map_err(|e|e.to_string())?;fs::write(root.join(format!("batch{batch}-weights.f32")),serial(&weights)).map_err(|e|e.to_string())?;
  controls.push(json!({"batch":batch,"all_rows_equal_singleton":all_equal,"prefill":compare(&unit,&expected)?,"native_decode":compare(&unit,&old)?,"output_sha256":hash(&serial(&output))}));
 }
 let report=json!({"utc_note":"operator experiment only","gpu_uuid":actual,"controls":controls,"lt_controls":lt_controls,"plan_sha256":hash(&fs::read(plan).map_err(|e|e.to_string())?),"scope":"Repeated actual equal current operand rows test batch-count effects, not realistic prompt synthesis. Original retained65 PTX and pedantic F32 GEMM/warp softmax. No serving selection, performance/fidelity/ADQ qualification."});fs::write(root.join("REPORT.json"),serde_json::to_vec_pretty(&report).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;println!("{}",report);Ok(())
}
fn main(){let v:Vec<_>=std::env::args().collect();if std::env::var("KRASIS_DEV_SCRIPT").as_deref()!=Ok("1")||v.len()!=3{eprintln!("Use ./dev stable-mla-probe <plan.json> <new-output-directory>");std::process::exit(2)}if let Err(e)=run(&v[1],&v[2]){eprintln!("{e}");std::process::exit(1)}}
